  // landing page
  "{pct}% of the 1,000,000,000 supply": "{pct} % der Gesamtmenge von 1.000.000.000",
  "0.5% of the transfer (min $0.05, max $50)": "0,5 % des Transfers (min. 0,05 $, max. 50 $)",
  "1% platform fee + the coin’s creator tax (0–3%)": "1 % Plattformgebühr + die Creator-Steuer des Coins (0–3 %)",
  "2% of each trade, in USDC": "2 % jedes Trades, in USDC",
  "85% — the other 15% rewards the trader’s referrer": "85 % — die anderen 15 % belohnen den Werber des Traders",
  "90% — Circle keeps 10%": "90 % — Circle behält 10 %",
  "A trading wallet in your browser: buy and sell in one tap, no pop-ups. Protect it with a passkey.": "Eine Trading-Wallet in deinem Browser: kaufen und verkaufen mit einem Tipp, ohne Pop-ups. Schütze sie mit einem Passkey.",
  "All of ARCDEX’s own fee revenue: its share of swap fees, launchpad fees and bridge fees. Referral rewards and creators’ shares are paid to them first; everything the platform keeps goes to buyback and burn.": "Alle eigenen Gebühreneinnahmen von ARCDEX: ihr Anteil an Swap-, Launchpad- und Bridge-Gebühren. Empfehlungsprämien und Creator-Anteile werden zuerst ausgezahlt; alles, was die Plattform behält, geht in Rückkauf und Burn.",
  "All platform fees land in the ARCDEX fee wallet — anyone can watch it on-chain.": "Alle Plattformgebühren landen in der ARCDEX-Gebühren-Wallet — jeder kann sie on-chain verfolgen.",
  "App": "App",
  "Arc explorer": "Arc-Explorer",
  "ARCDEX is the social trading app for Arc: a terminal for every new coin, one-tap trading, live trader activity, clans, leaderboards and a launchpad. Everything settles on-chain in USDC, and you always keep your own keys.": "ARCDEX ist die Social-Trading-App für Arc: ein Terminal für jeden neuen Coin, Trading mit einem Tipp, Live-Aktivität der Trader, Clans, Ranglisten und ein Launchpad. Alles wird on-chain in USDC abgewickelt, und deine Schlüssel behältst du immer selbst.",
  "Bridge (Circle CCTP)": "Bridge (Circle CCTP)",
