  "Whitepaper (PDF)": "Whitepaper (PDF)",
  ". It's a separate launch that reuses the": ". Es ist ein anderer Launch, der den Ticker nutzt:",
  "Every trade is simulated before it's sent. The pool's own fee, set by {launchpad}, applies on top of the platform fee.": "Jeder Trade wird vor dem Senden simuliert. Die Pool-Gebühr, von {launchpad} festgelegt, kommt zur Plattformgebühr hinzu.",
  "Trade on {launchpad} ↗": "Auf {launchpad} traden ↗",
  "{symbol} trades on {launchpad}'s own contracts, which ARCDEX can't route yet.": "{symbol} wird über die eigenen Verträge von {launchpad} gehandelt, die ARCDEX noch nicht routen kann.",
  "{launchpad} curve": "{launchpad}-Kurve",
  "Curve fee": "Kurvengebühr",
  "Snipe tax": "Snipe-Steuer",
  "I accept the {pct} snipe tax on this buy.": "Ich akzeptiere die Snipe-Steuer von {pct} auf diesen Kauf.",
  "{symbol} launched moments ago: a {pct} snipe tax goes to the launchpad on this buy, falling to 0 shortly after launch. Tick the box to buy anyway, or wait.": "{symbol} ist gerade erst gestartet: Auf diesen Kauf geht eine Snipe-Steuer von {pct} an das Launchpad; sie fällt kurz nach dem Start auf 0. Setze das Häkchen, um trotzdem zu kaufen, oder warte.",
  "This curve has sold out and is moving to its Uniswap pool: buying reopens there shortly. You can still sell.": "Diese Kurve ist ausverkauft und zieht in ihren Uniswap-Pool um: Käufe sind dort gleich wieder möglich. Verkaufen kannst du weiterhin.",
  "Every trade is simulated before it's sent. {launchpad}'s curve charges its own fee; ARCDEX adds none.": "Jeder Trade wird vor dem Senden simuliert. Die Kurve von {launchpad} erhebt ihre eigene Gebühr; ARCDEX schlägt nichts auf.",
  "Every trade is simulated before it's sent. {launchpad}'s curve charges its own fee on top of the platform fee.": "Jeder Trade wird vor dem Senden simuliert. Die Kurve von {launchpad} erhebt ihre eigene Gebühr, die zur Plattformgebühr hinzukommt.",
  "On {launchpad}'s bonding curve: {pct} of the way to its Uniswap pool.": "Auf der Bonding-Kurve von {launchpad}: {pct} des Wegs zu ihrem Uniswap-Pool.",
  "2% of each curve trade, in USDC; 15% of it to the trader's referrer": "2 % jedes Kurven-Trades, in USDC; 15 % davon gehen an den Werber des Traders",
  "A router built from this exact code buys 5 USDC of a live Mercuri and SolonPad coin and sells it back, inside a simulated transaction on Arc. It checks the fee, the referral share and that the router keeps nothing.": "Ein Router aus genau diesem Code kauft für 5 USDC einen aktiven Mercuri- und SolonPad-Coin und verkauft ihn wieder – in einer simulierten Transaktion auf Arc. Geprüft werden die Gebühr, der Werber-Anteil und dass der Router nichts behält.",
  "ARCDEX already routes curve trades through": "ARCDEX leitet Kurven-Trades bereits über",
  "ARCDEX already uses this router.": "ARCDEX nutzt diesen Router bereits.",
  "ARCDEX's swap router and launchpad are owned by {deployer}. Deploying from that wallet keeps one owner for all three; any wallet you control works.": "Swap-Router und Launchpad von ARCDEX gehören {deployer}. Wer von dieser Wallet deployt, hat einen Owner für alle drei; jede Wallet, die du kontrollierst, funktioniert.",
  "Add a little USDC to this wallet on Arc for gas first.": "Lade zuerst etwas USDC auf Arc in diese Wallet, für das Gas.",
  "All simulated trades passed.": "Alle simulierten Trades bestanden.",
  "ArcDexCurveRouter takes ARCDEX's 2% fee on Mercuri and SolonPad curve trades. Deploy it once, from your own wallet. Nothing on ARCDEX changes until you switch it on (step 4).": "ArcDexCurveRouter erhebt die 2-%-Gebühr von ARCDEX auf Kurven-Trades bei Mercuri und SolonPad. Deploye ihn einmal, aus deiner eigenen Wallet. Auf ARCDEX ändert sich nichts, bis du ihn einschaltest (Schritt 4).",
  "ArcDexCurveRouter v1, compiled from contracts/ArcDexCurveRouter.sol: the code its 43 tests ran": "ArcDexCurveRouter v1, kompiliert aus contracts/ArcDexCurveRouter.sol: der Code, mit dem seine 43 Tests liefen",
  "Buy {value} through the router: exactly {fee} to the fee wallet, and the rest bought {tokens} tokens, as many as buying on the curve directly": "Kauf für {value} über den Router: genau {fee} an die Gebühren-Wallet, der Rest kaufte {tokens} Token, so viele wie ein direkter Kauf auf der Kurve",
  "Check it": "Prüfen",
  "Check the deployed contract": "Den deployten Vertrag prüfen",
  "Compares its code with the tested build, reads its settings back and simulates the same trades through it. This runs by itself after deploying; you can also check a router deployed another way.": "Vergleicht seinen Code mit dem getesteten Build, liest seine Einstellungen zurück und simuliert dieselben Trades über ihn. Das läuft nach dem Deployen von selbst; du kannst auch einen anders deployten Router prüfen.",
  "Connect the wallet that will own the router: MetaMask, Rabby, a hardware wallet… It pays the deployment gas in USDC.": "Verbinde die Wallet, der der Router gehören soll: MetaMask, Rabby, eine Hardware-Wallet … Sie zahlt das Gas fürs Deployen in USDC.",
  "Contract": "Vertrag",
  "Costs about {cost} in gas. Your wallet has {balance}.": "Kostet etwa {cost} an Gas. Deine Wallet hat {balance}.",
  "Couldn't estimate the cost; your wallet shows it before you confirm.": "Kosten ließen sich nicht schätzen; deine Wallet zeigt sie an, bevor du bestätigst.",
  "Couldn't read {venue}'s launches: the network is busy. Try again.": "Die Launches von {venue} ließen sich nicht lesen: Das Netzwerk ist ausgelastet. Versuch es noch einmal.",
  "Deploy anyway": "Trotzdem deployen",
  "Deploy it from your wallet": "Aus deiner Wallet deployen",
