  "Every check passed.": "Alle Prüfungen bestanden.",
  "Fee {fee} of each trade, {share} of it to the referrer; {state}": "Gebühr {fee} pro Trade, davon {share} an den Werber; {state}",
  "Fees go to ARCDEX's fee wallet, {wallet}": "Gebühren gehen an die Gebühren-Wallet von ARCDEX, {wallet}",
  "Fees go to {wallet}, not ARCDEX's fee wallet {expected}.": "Gebühren gehen an {wallet}, nicht an die Gebühren-Wallet von ARCDEX {expected}.",
  "Finding a coin on each curve and simulating its trades…": "Suche auf jeder Kurve einen Coin und simuliere seine Trades …",
  "Its code is ArcDexCurveRouter v1 as tested (only the compiler metadata differs)": "Sein Code ist ArcDexCurveRouter v1 wie getestet (nur die Compiler-Metadaten weichen ab)",
  "Its code is ArcDexCurveRouter v1, byte for byte as tested": "Sein Code ist ArcDexCurveRouter v1, Byte für Byte wie getestet",
  "Its owner is {owner}, not your wallet.": "Sein Owner ist {owner}, nicht deine Wallet.",
  "Launchpads": "Launchpads",
  "No coin is on a Mercuri or SolonPad curve right now: nothing could be simulated.": "Gerade ist kein Coin auf einer Mercuri- oder SolonPad-Kurve: Es konnte nichts simuliert werden.",
  "Once a deployed router passes every check, its address shows here, ready to switch on.": "Sobald ein deployter Router alle Prüfungen besteht, erscheint seine Adresse hier, bereit zum Einschalten.",
  "Owned by your wallet, {owner}": "Gehört deiner Wallet, {owner}",
