  "Referred buy, then sell it all back: {share} of each fee to the referrer, the rest to the fee wallet, nothing left in the router": "Geworbener Kauf, dann alles zurückverkauft: {share} jeder Gebühr an den Werber, der Rest an die Gebühren-Wallet, nichts bleibt im Router",
