  "Switch it on": "Einschalten",
  "The contract at this address isn't ArcDexCurveRouter v1 as tested.": "Der Vertrag an dieser Adresse ist nicht ArcDexCurveRouter v1 wie getestet.",
  "The deployment failed on-chain.": "Das Deployment ist on-chain fehlgeschlagen.",
  "The simulation found problems. Deploy anyway?": "Die Simulation hat Probleme gefunden. Trotzdem deployen?",
  "The simulation found problems: see the ✗ lines above.": "Die Simulation hat Probleme gefunden: siehe die ✗-Zeilen oben.",
  "The trading wallet can't deploy it: the owner should be a wallet you hold outside this site.": "Die Trading-Wallet kann ihn nicht deployen: Owner sollte eine Wallet sein, die du außerhalb dieser Seite hältst.",
  "The wallet that deploys it. It can change the fee (up to 2%), the referral share and the fee wallet, and pause trading. It can't touch traders' funds: the router holds none between trades.": "Die Wallet, die ihn deployt. Sie kann die Gebühr (bis 2 %), den Werber-Anteil und die Gebühren-Wallet ändern und den Handel pausieren. An die Gelder der Trader kommt sie nicht: Der Router hält zwischen Trades keine.",
  "There is no contract at {address}.": "Unter {address} gibt es keinen Vertrag.",
  "This network's RPC can't run the simulation (it doesn't take state overrides). You can still deploy: the checks after deploying compare its code with the tested build.": "Der RPC dieses Netzwerks kann die Simulation nicht ausführen (er nimmt keine State-Overrides an). Du kannst trotzdem deployen: Die Prüfungen danach vergleichen seinen Code mit dem getesteten Build.",
  "This network's RPC can't simulate trades (no state overrides), so they were skipped.": "Der RPC dieses Netzwerks kann keine Trades simulieren (keine State-Overrides), daher wurden sie übersprungen.",
  "Trades coins of the Mercuri factory {mercuri} and the SolonPad factory {solon}": "Handelt Coins der Mercuri-Factory {mercuri} und der SolonPad-Factory {solon}",
  "What gets deployed": "Was deployt wird",
