  "each signal opens a simulated position at the live price, with real costs. No money moves.": "Jedes Signal eröffnet eine simulierte Position zum Live-Preis, mit echten Kosten. Es fließt kein Geld.",
  "These are measured results, not a promise: no strategy can guarantee a win rate, and most new coins go to zero. Not financial advice.": "Das sind gemessene Ergebnisse, kein Versprechen: Keine Strategie kann eine Gewinnquote garantieren, und die meisten neuen Coins fallen auf null. Keine Finanzberatung.",
