  "open": "offen",
  "New coins that pass every hard safety check and show real buying, from every Arc launchpad.": "Neue Coins, die jede harte Sicherheitsprüfung bestehen und echte Käufe zeigen, von jedem Arc-Launchpad.",
  "took profit": "Gewinn mitgenommen",
  "profit taken, trailing": "Gewinn mitgenommen, Trailing",
  "Fast scalp": "Schneller Scalp",
  "Coins with a risk flag (the creator holds a big stake, launches coin after coin, or copies a ticker) are traded small and fast: a fifth of the size, most of it sold at +30%, out the moment the creator sells, never held over 15 minutes.": "Coins mit einem Risikohinweis (der Ersteller hält einen großen Anteil, startet Coin um Coin oder kopiert einen Ticker) werden klein und schnell gehandelt: ein Fünftel der Größe, das meiste bei +30 % verkauft, raus, sobald der Ersteller verkauft, nie länger als 15 Minuten gehalten.",
  "Risky:": "Riskant:",
  "the creator sold": "der Ersteller hat verkauft",
  "Live mode:": "Live-Modus:",
  "the bot wallet also buys and sells each signal with real USDC, within hard limits.": "die Bot-Wallet kauft und verkauft jedes Signal zusätzlich mit echtem USDC, innerhalb fester Limits.",
  "Results": "Ergebnisse",
  "Paper": "Papier",
