  "PAPER": "PAPIER",
  "Trading mode": "Handelsmodus",
  "Signals are traded with real money from the bot wallet.": "Signale werden mit echtem Geld aus der Bot-Wallet gehandelt.",
  "The bot is off on this engine.": "Der Bot ist auf dieser Engine aus.",
  "Signals open simulated positions. No money moves.": "Signale eröffnen simulierte Positionen. Es fließt kein Geld.",
  "Only the owner's wallet can switch modes.": "Nur die Wallet des Eigentümers kann den Modus wechseln.",
  "No owner wallet is set on the engine, so the mode can't be switched here.": "Auf der Engine ist keine Eigentümer-Wallet gesetzt, daher lässt sich der Modus hier nicht wechseln.",
  "Switch to live trading?": "Zu Live-Handel wechseln?",
  "From now on the bot buys and sells every signal it can reach with the bot wallet's USDC. Trades can lose money, and most new coins go to zero.": "Ab jetzt kauft und verkauft der Bot jedes erreichbare Signal mit dem USDC der Bot-Wallet. Trades können Geld verlieren, und die meisten neuen Coins fallen auf null.",
  "Cancel": "Abbrechen",
  "Waiting for your signature…": "Warte auf deine Signatur…",
  "Sign and go live": "Signieren und live gehen",
  "Bot wallet": "Bot-Wallet",
  "USDC on Arc": "USDC auf Arc",
  "Live P&L today": "Live-P&L heute",
  "Live positions open": "Offene Live-Positionen",
  "Sell all {n} live positions now, at any price the pools give?": "Alle {n} Live-Positionen jetzt verkaufen, zu jedem Preis, den die Pools geben?",
  "Sign and sell all": "Signieren und alles verkaufen",
  "Sell all live positions": "Alle Live-Positionen verkaufen",
  "Live trading needs a bot wallet on the engine: set BOT_PRIVATE_KEY (a new wallet that holds only what the bot may trade) in Railway, then fund it with USDC on Arc.": "Live-Handel braucht eine Bot-Wallet auf der Engine: BOT_PRIVATE_KEY (eine neue Wallet, die nur hält, was der Bot handeln darf) in Railway setzen und dann mit USDC auf Arc aufladen.",
  "Live trading is not set up on this engine.": "Live-Handel ist auf dieser Engine nicht eingerichtet.",
  "Limits: up to ${a} a trade · {o} open at once ({s} scalps) · stops for the day after a ${d} loss · keeps ${r} for gas · buys at most {b}% under the quote": "Limits: bis ${a} pro Trade · {o} gleichzeitig offen ({s} Scalps) · Stopp für den Tag nach ${d} Verlust · behält ${r} für Gas · kauft höchstens {b}% unter dem Kurs",
  "Every buy is checked first: the bot's wallet simulates the buy and selling it all straight back. A coin it couldn't sell, or a round trip costing over {p}%, is never bought.": "Jeder Kauf wird zuerst geprüft: Die Wallet des Bots simuliert den Kauf und den sofortigen Verkauf von allem. Ein Coin, den er nicht verkaufen könnte, oder ein Hin und Zurück, das mehr als {p} % kostet, wird nie gekauft.",
  "each buy simulated with its sale first (round trip at most {p}%)": "jeder Kauf wird vorher mit seinem Verkauf simuliert (Hin und Zurück höchstens {p} %)",
  "Latest signal": "Neuestes Signal",
  "Signals: the bot's picks and results": "Signale: die Picks und Ergebnisse des Bots",
  "sold by the owner": "vom Eigentümer verkauft",
  "buy": "Kauf",
  "sell": "Verkauf",
  "approval": "Freigabe",
  "My autotrade": "Mein Autotrade",
  "Scanner": "Scanner",
  "Bot results": "Bot-Ergebnisse",
  "Autotrade": "Autotrade",
  "Autotrade scans every new coin on every Arc launchpad, rejects the unsafe ones and trades the rest with the strategies you choose. Start with virtual USDC: paper trading, no money moves.": "Autotrade prüft jeden neuen Coin auf jedem Arc-Launchpad, lehnt die unsicheren ab und handelt den Rest mit den Strategien deiner Wahl. Starte mit virtuellem USDC: Papierhandel, es fließt kein Geld.",
  "Scanning {n} coins": "Prüft {n} Coins",
  "{n} checks/min": "{n} Prüfungen/Min.",
  "last check": "letzte Prüfung",
  "{n} signals today": "{n} Signale heute",
  "{n} rejected today": "{n} heute abgelehnt",
  "Connecting to the scanner…": "Verbinde mit dem Scanner…",
  "Rejected": "Abgelehnt",
  "Checking": "Wird geprüft",
  "Watching": "Beobachtet",
  "Signal": "Signal",
  "Every coin being scanned, and why": "Jeder geprüfte Coin, und warum",
  "No coins here right now.": "Gerade keine Coins hier.",
  "launched": "gestartet",
  "checked": "geprüft",
  "Try Autotrade with virtual USDC": "Teste Autotrade mit virtuellem USDC",
  "Get a paper account, deposit virtual USDC, pick your strategies and press Start. It trades every matching signal around the clock, even with this page closed. No wallet or real money needed.": "Hol dir ein Papierkonto, zahl virtuelles USDC ein, wähle deine Strategien und drück Start. Es handelt jedes passende Signal rund um die Uhr, auch wenn diese Seite geschlossen ist. Keine Wallet und kein echtes Geld nötig.",
  "Create my paper account": "Mein Papierkonto erstellen",
  "Keep at least one strategy.": "Behalte mindestens eine Strategie.",
  "Running": "Läuft",
  "Stopped": "Gestoppt",
  "Paper account": "Papierkonto",
  "virtual USDC": "virtuelles USDC",
  "started": "gestartet",
