  "Profit / loss": "Gewinn / Verlust",
  "on {d} deposited": "auf {d} eingezahlt",
  "Deposit virtual USDC": "Virtuelles USDC einzahlen",
  "Strategies": "Strategien",
  "use one, or several at once": "eine oder mehrere gleichzeitig",
  "Amount per trade": "Betrag pro Trade",
  "Now {v} a trade; fast scalps use a fifth of it.": "Jetzt {v} pro Trade; schnelle Scalps nutzen ein Fünftel davon.",
  "Stop trading": "Handel stoppen",
