  "3. Fund its own wallet": "3. Eigene Wallet aufladen",
  "Make its live wallet": "Live-Wallet erstellen",
  "Send USDC on Arc to this address: at least {m} to go live. It trades up to {x} a trade and keeps {r} for gas. Only this bot uses it.": "Sende USDC auf Arc an diese Adresse: mindestens {m}, um live zu gehen. Er handelt bis {x} pro Trade und behält {r} für Gas. Nur dieser Bot nutzt sie.",
  "Wallet balance": "Wallet-Guthaben",
  "Live P&L": "Live-G&V",
  "Platform fees paid": "Gezahlte Plattformgebühren",
  "2% of winning trades' profit": "2 % des Gewinns aus Gewinn-Trades",
  "4. Switch it": "4. Umschalten",
  "Sell all live positions ({n})": "Alle Live-Positionen verkaufen ({n})",
  "Real money: this bot will trade its wallet's USDC on every signal it takes, with its learned settings, until you switch it back. 2% of each winning trade's profit goes to the platform; losing trades pay nothing. Results aren't guaranteed: most new coins go to zero.": "Echtes Geld: Dieser Bot handelt mit den USDC seiner Wallet bei jedem Signal, das er nimmt, mit seinen gelernten Einstellungen, bis du zurückschaltest. 2 % des Gewinns jedes Gewinn-Trades gehen an die Plattform; Verlust-Trades zahlen nichts. Ergebnisse sind nicht garantiert: Die meisten neuen Coins fallen auf null.",
  "Yes, trade live": "Ja, live handeln",
  "To address": "Zieladresse",
  "Bot marketplace": "Bot-Marktplatz",
  "Every bot on ARCDEX, with its results and what it holds right now. Paper bots trade virtual USDC; live bots trade their own wallet.": "Jeder Bot auf ARCDEX, mit seinen Ergebnissen und dem, was er gerade hält. Papier-Bots handeln virtuelle USDC; Live-Bots handeln mit ihrer eigenen Wallet.",
