  "New coins in their first 10 minutes that pass every safety check and show real buying. Sold in full at the take-profit (+40% to start), aiming for $1–5 a trade.": "Neue Coins in ihren ersten 10 Minuten, die jede Sicherheitsprüfung bestehen und echte Käufe zeigen. Vollständig beim Take-Profit verkauft (anfangs +40 %), Ziel 1–5 $ pro Trade.",
  "Coins that ran 2× or more, pulled back 25–70% and are being bought again. Sold in full at the take-profit (+35% to start), aiming for $1–5, held up to 6 hours.": "Coins, die 2× oder mehr gestiegen, um 25–70 % zurückgekommen sind und wieder gekauft werden. Vollständig beim Take-Profit verkauft (anfangs +35 %), Ziel 1–5 $, bis zu 6 Stunden gehalten.",
