  "Social": "Social",
  "Follow traders, join clans.": "Folge Tradern, tritt Clans bei.",
  "Your own trading bot on ARCDEX. It scans every new coin on Arc, skips the unsafe ones and trades the rest with the strategies you pick, around the clock.": "Dein eigener Trading-Bot auf ARCDEX. Er scannt jeden neuen Coin auf Arc, lässt unsichere aus und handelt den Rest rund um die Uhr mit den Strategien, die du wählst.",
  "How does a bot improve itself?": "Wie verbessert sich ein Bot selbst?",
  "After trades close, it reads its losing ones and adjusts its take-profit and entry filters. Every change is logged with its reason, and a change that makes it win less is rolled back.": "Nach geschlossenen Trades liest er die verlorenen und passt Take-Profit und Einstiegsfilter an. Jede Änderung wird mit Grund protokolliert, und eine Änderung, die seltener gewinnt, wird zurückgenommen.",
  "Is my money at risk?": "Ist mein Geld in Gefahr?",
  "Every bot starts on paper with virtual USDC. It can go live once its record earns it. Live trading uses real money and can lose it. Nothing here is financial advice.": "Jeder Bot startet im Paper-Modus mit virtuellen USDC. Live geht er erst, wenn seine Bilanz es rechtfertigt. Live-Trading nutzt echtes Geld und kann es verlieren. Nichts hier ist Finanzberatung.",
  "The official ARCDEX coin: a fixed supply of 1,000,000,000 with no mint function. Platform fees buy it back and burn it.": "Der offizielle ARCDEX-Coin: ein festes Angebot von 1.000.000.000 ohne Mint-Funktion. Plattformgebühren kaufen ihn zurück und verbrennen ihn.",
