  "The official ARCDEX coin. A fixed supply of 1B with no mint function. Platform fees buy it back and burn it.": "Der offizielle ARCDEX-Coin. Festes Angebot von 1 Mrd. ohne Mint-Funktion. Plattformgebühren kaufen ihn zurück und verbrennen ihn.",
