  "Regime": "Regime",
  "The signal engine isn't answering right now. It runs inside the market engine; this page fills in when it's back.": "Die Signal-Engine antwortet gerade nicht. Sie läuft in der Markt-Engine; diese Seite füllt sich, sobald sie zurück ist.",
  "Signal history": "Signalverlauf",
  "Paper trades": "Papier-Trades",
  "Validation & live gate": "Validierung & Live-Freigabe",
  "Controls": "Steuerung",
  "A 100-point score for every coin from its buying and selling, momentum, volume, liquidity, smart-money wallets, holders, safety and the market's mood; three strategies on top; paper trading with live data, every trade filled at live speed with its costs. Live trading stays off until walk-forward tests and the paper record pass every check below.": "Ein 100-Punkte-Score für jeden Coin aus Käufen und Verkäufen, Momentum, Volumen, Liquidität, Smart-Money-Wallets, Haltern, Sicherheit und Marktstimmung; darauf drei Strategien; Papierhandel mit Live-Daten, jeder Trade in Live-Geschwindigkeit samt Kosten ausgeführt. Echter Handel bleibt aus, bis Walk-forward-Tests und die Papierbilanz alle Prüfungen unten bestehen.",
