  "Scored on every trade, at most once a second. A strategy column means its conditions are met right now.": "Bei jedem Trade bewertet, höchstens einmal pro Sekunde. Eine Strategie in der Spalte heißt: Ihre Bedingungen sind jetzt erfüllt.",
