  "Slippage": "Slippage",
  "A signal is a strategy's conditions met. Each one says why it triggered, and why it was traded or not.": "Ein Signal heißt: Die Bedingungen einer Strategie sind erfüllt. Jedes sagt, warum es ausgelöst wurde und warum es gehandelt wurde oder nicht.",
  "Traded": "Gehandelt",
  "Not traded": "Nicht gehandelt",
  "No signals yet. Most coins never meet a strategy's conditions; a signal shows here the moment one does.": "Noch keine Signale. Die meisten Coins erfüllen nie die Bedingungen einer Strategie; ein Signal erscheint hier, sobald einer es tut.",
