  "Open the coin": "Coin öffnen",
  "Virtual USDC, live prices: each buy fills at the first price 2.5 seconds after the signal and each sale 2 seconds after its trigger, paying the pool's price impact, fees, taxes and gas.": "Virtuelle USDC, echte Preise: Jeder Kauf wird zum ersten Preis 2,5 Sekunden nach dem Signal ausgeführt, jeder Verkauf 2 Sekunden nach seinem Auslöser, inklusive Preisauswirkung im Pool, Gebühren, Steuern und Gas.",
  "No paper trades yet.": "Noch keine Papier-Trades.",
