  "Futures are paused: new positions can’t open right now.": "Futures sind pausiert: neue Positionen können gerade nicht eröffnet werden.",
  "Check the amount and leverage: at least the minimum margin, and no more than the market’s leverage.": "Prüfe Betrag und Hebel: mindestens die Mindestmarge und nicht mehr als der Hebel des Markts.",
  "A close for this position is already on its way.": "Ein Schließen dieser Position ist bereits unterwegs.",
  "Too early: a market request can be cancelled once its time to execute has passed.": "Zu früh: Eine Market-Anfrage kann storniert werden, sobald ihre Ausführungszeit abgelaufen ist.",
  "Shares can leave 15 minutes after your last deposit.": "Anteile können 15 Minuten nach deiner letzten Einzahlung abgezogen werden.",
