  "soon": "bald",
  "Open interest": "Open Interest",
  "Oracle prices from RedStone, signed every 10 seconds: the prices positions open, close and liquidate at.": "Oracle-Preise von RedStone, alle 10 Sekunden signiert: die Preise, zu denen Positionen eröffnet, geschlossen und liquidiert werden.",
  "Oracle prices are loading…": "Oracle-Preise werden geladen…",
