  "Take-profit price": "Take-Profit-Preis",
  "Stop-loss price": "Stop-Loss-Preis",
  "For a long, the take-profit is above the entry and the stop-loss below it.": "Bei einem Long liegt der Take-Profit über dem Einstieg und der Stop-Loss darunter.",
