  "Max price move": "Max. Preisbewegung",
  "Your order fills at the first oracle price signed after it reaches the chain, usually within 30 seconds. If it would fill beyond your max price move, it’s cancelled and refunded.": "Deine Order wird zum ersten Oracle-Preis ausgeführt, der signiert wurde, nachdem sie die Chain erreicht hat, meist innerhalb von 30 Sekunden. Würde sie jenseits deiner max. Preisbewegung ausgeführt, wird sie storniert und erstattet.",
