  "The pool opens once futures are deployed on Arc testnet.": "Der Pool öffnet, sobald Futures im Arc-Testnet bereitgestellt sind.",
  "Reserved for open positions": "Reserviert für offene Positionen",
  "Use": "Auslastung",
  "Share price": "Anteilspreis",
  "Your shares": "Deine Anteile",
  "The pool takes the other side of every trade: it keeps traders’ losses and borrow fees and pays their profits. Each position’s largest possible profit is set aside when it opens, so the pool can always pay.": "Der Pool ist die Gegenseite jedes Trades: Er behält die Verluste und Leihgebühren der Trader und zahlt ihre Gewinne. Der größtmögliche Gewinn jeder Position wird bei ihrer Eröffnung zurückgelegt, daher kann der Pool immer zahlen.",
  "Deposit test USDC": "Test-USDC einzahlen",
  "Withdraw shares (sLP)": "Anteile abziehen (sLP)",
  "to add liquidity.": "um Liquidität hinzuzufügen.",
  "Latest futures trades": "Neueste Futures-Trades",
