  "Stop-loss": "Stop-Loss",
  "Cancelled": "Storniert",
  // Landing: futures on Arc testnet (2026-10-03)
  "BTC, ETH and SOL perpetuals, on Arc testnet.": "BTC-, ETH- und SOL-Perpetuals im Arc-Testnet.",
  "Signed oracle prices": "Signierte Oracle-Preise",
  "Positions are priced by RedStone’s signed oracle prices, checked on-chain, not by thin pools anyone can push.": "Positionen werden zu RedStones signierten Oracle-Preisen bewertet, on-chain geprüft, nicht über dünne Pools, die jeder verschieben kann.",
  "A spot and perpetual futures exchange on Arc: a live market for every coin, one-tap swaps, a multichain USDC bridge and BTC, ETH and SOL perpetuals, now on Arc testnet.": "Eine Börse für Spot und Perpetual Futures auf Arc: ein Live-Markt für jeden Coin, Swaps mit einem Tippen, eine Multichain-USDC-Bridge und BTC-, ETH- und SOL-Perpetuals, jetzt im Arc-Testnet.",
  "They’re on Arc testnet now: try them with free test USDC, without risk. Mainnet follows an independent security audit; the date will be announced.": "Sie sind jetzt im Arc-Testnet: probiere sie risikofrei mit kostenlosen Test-USDC aus. Das Mainnet folgt nach einem unabhängigen Sicherheitsaudit; der Termin wird angekündigt.",
  "Trade every coin on Arc in one tap, and go long or short on BTC, ETH and SOL with up to 10× leverage, now on Arc testnet. All in USDC.": "Handle jeden Coin auf Arc mit einem Tipp und gehe long oder short auf BTC, ETH und SOL mit bis zu 10× Hebel, jetzt im Arc-Testnet. Alles in USDC.",
  "On testnet": "Im Testnet",
  "Try them on Arc testnet with free test USDC. Mainnet after an independent audit.": "Probiere sie im Arc-Testnet mit kostenlosen Test-USDC aus. Mainnet nach einem unabhängigen Audit.",
  "Perpetual futures on Arc": "Perpetual Futures auf Arc",
  "Long or short BTC, ETH and SOL with up to 10× leverage, settled in USDC at RedStone’s signed oracle prices. On Arc testnet now; mainnet after an independent audit.": "Long oder short auf BTC, ETH und SOL mit bis zu 10× Hebel, abgerechnet in USDC zu RedStones signierten Oracle-Preisen. Jetzt im Arc-Testnet; Mainnet nach einem unabhängigen Audit.",
  // $ARCDEX buyback & burn, 30% / 70% (2026-10-03)
  "$ARCDEX burn": "$ARCDEX-Burn",
  "$ARCDEX": "$ARCDEX",
  "Fees fund liquidity": "Gebühren finanzieren Liquidität",
  "70% of ARCDEX’s fees go to liquidity pools, and 30% buy back $ARCDEX and burn it.": "70 % der Gebühren von ARCDEX fließen in Liquiditätspools, 30 % kaufen $ARCDEX zurück und verbrennen es.",
  "The ARCDEX coin, launched on Argus. 30% of ARCDEX’s fees buy back $ARCDEX and burn it, and 70% go to liquidity pools. Every buyback and burn is on-chain and shown on this page.": "Der Coin von ARCDEX, gestartet auf Argus. 30 % der Gebühren von ARCDEX kaufen $ARCDEX zurück und verbrennen es, 70 % fließen in Liquiditätspools. Jeder Rückkauf und jeder Burn ist on-chain und auf dieser Seite zu sehen.",
  "Where the fees go": "Wohin die Gebühren gehen",
  "Of the fees ARCDEX collects, 30% buy back $ARCDEX and burn it, and 70% go to liquidity pools. Every number is read from the fee wallet on Arc.": "Von den Gebühren, die ARCDEX einnimmt, kaufen 30 % $ARCDEX zurück und verbrennen es, 70 % fließen in Liquiditätspools. Jede Zahl wird aus der Gebühren-Wallet auf Arc gelesen.",
  "Bought back": "Zurückgekauft",
  "$ARCDEX burned": "Verbrannte $ARCDEX",
  "Still to buy": "Noch zu kaufen",
  "Liquidity pools": "Liquiditätspools",
