  "Still to add": "Noch hinzuzufügen",
  "Fees collected": "Eingenommene Gebühren",
  "See the full ledger": "Das vollständige Register ansehen",
  "The fee wallet on the explorer": "Die Gebühren-Wallet im Explorer",
  "$ARCDEX buyback & burn": "$ARCDEX-Rückkauf & Burn",
  "Of the fees ARCDEX collects, 30% buy back $ARCDEX and burn it, and 70% go to liquidity pools. Every number below is read from the fee wallet on Arc, so anyone can check it.": "Von den Gebühren, die ARCDEX einnimmt, kaufen 30 % $ARCDEX zurück und verbrennen es, 70 % fließen in Liquiditätspools. Jede Zahl unten wird aus der Gebühren-Wallet auf Arc gelesen, damit jeder sie prüfen kann.",
  "The ledger can’t be reached right now. Try again in a moment.": "Das Register ist gerade nicht erreichbar. Versuche es gleich noch einmal.",
  "since 3 October 2026": "seit dem 3. Oktober 2026",
