  "Add liquidity": "Liquidität hinzufügen",
  "to add": "hinzuzufügen",
  "Add it from this wallet to a pool (or to the futures pool on mainnet); the ledger counts it by itself.": "Füge sie aus dieser Wallet einem Pool hinzu (oder dem Futures-Pool im Mainnet); das Register zählt sie von selbst.",
  "Buybacks, burns and liquidity": "Rückkäufe, Burns und Liquidität",
  "Nothing yet: the first buyback and burn will show here.": "Noch nichts: Der erste Rückkauf und Burn erscheinen hier.",
  "Latest fees": "Neueste Gebühren",
  "No fees since the program started.": "Keine Gebühren seit dem Start des Programms.",
  "How it’s counted: fees are USDC that reached the fee wallet from trades and other platform activity. A buyback is a fee-wallet transaction that brought $ARCDEX in; a burn is $ARCDEX it sent to 0x…dEaD; liquidity is value it put into a pool. Burning reduces supply; it doesn’t promise any price.": "So wird gezählt: Gebühren sind USDC, die durch Trades und andere Plattformaktivität in der Gebühren-Wallet ankamen. Ein Rückkauf ist eine Transaktion der Gebühren-Wallet, die $ARCDEX hereinbrachte; ein Burn sind $ARCDEX, die sie an 0x…dEaD schickte; Liquidität ist der Wert, den sie in einen Pool einbrachte. Verbrennen verringert das Angebot; es verspricht keinen Preis.",
