  "No network matches.": "Kein Netzwerk passt.",
  "Native USDC between Arc and {n} networks, with Circle’s CCTP: no wrapped tokens, no third-party bridge, usually under a minute.": "Natives USDC zwischen Arc und {n} Netzwerken, mit Circles CCTP: keine Wrapped Tokens, keine Drittanbieter-Bridge, meist in unter einer Minute.",
