  "On Arc? Start trading": "Auf Arc? Jetzt handeln",
  "USDC on Arc trades every coin on ARCDEX, spot and futures.": "Mit USDC auf Arc handelst du jeden Coin auf ARCDEX, Spot und Futures.",
  "Swap USDC for any coin on Arc in one tap, and back. USDC on another chain? Bring it over in about a minute.": "Tausche USDC mit einem Tippen gegen jeden Coin auf Arc, und zurück. USDC auf einer anderen Chain? In etwa einer Minute herüberholen.",
  "Pay with USDC, or sell a coin back to USDC": "Mit USDC bezahlen oder einen Coin zurück in USDC verkaufen",
  "Trades go through ARCDEX's swap router (launchpad coins on their bonding curve). Every trade is simulated first, and approvals are for the exact amount only.": "Trades laufen über den Swap-Router von ARCDEX (Launchpad-Coins über ihre Kurve). Jeder Trade wird zuerst simuliert, und Freigaben gelten nur für den genauen Betrag.",
