  "Trade every chain. Hold $ARCDEX.": "Handeln Sie auf jeder Chain. Halten Sie $ARCDEX.",
  "Multichain Decentralized Exchange": "Dezentrale Multichain-Börse",
  "$ARCDEX is ARCDEX’s platform coin. 30% of ARCDEX’s fees buy it back and burn it, and 70% go to liquidity pools. Every number below is read from Arc, so anyone can check it.": "$ARCDEX ist der Plattform-Coin von ARCDEX. 30 % der Gebühren von ARCDEX kaufen ihn zurück und verbrennen ihn, 70 % gehen in Liquiditätspools. Jede Zahl unten wird von Arc gelesen, sodass jeder sie prüfen kann.",
