  "Every burn": "Jeder Burn",
  "Not a launchpad coin: ARCDEX only lists and sells coins launched on a launchpad (and Robinhood’s stock tokens), because coins from unknown contracts can be malicious. You can still sell any you hold.": "Kein Launchpad-Coin: ARCDEX listet und verkauft nur auf einem Launchpad gestartete Coins (und Robinhoods Aktien-Token), weil Coins aus unbekannten Verträgen bösartig sein können. Sie können Ihre Bestände weiterhin verkaufen.",
  "⚠ This coin wasn’t launched on a launchpad, so ARCDEX doesn’t list it or offer it to buy. Coins from unknown contracts can be malicious.": "⚠ Dieser Coin wurde nicht auf einem Launchpad gestartet, daher listet ARCDEX ihn nicht und bietet ihn nicht zum Kauf an. Coins aus unbekannten Verträgen können bösartig sein.",
