  "Off: coins rated Danger, and pool coins under ${usd} of liquidity or {holders} holders, are left out.": "Aus: Coins mit der Bewertung Gefahr sowie Pool-Coins unter ${usd} Liquidität oder {holders} Haltern werden ausgeblendet.",
  "Show risky coins": "Riskante Coins anzeigen",
  "Hidden by the safety standard: {n} (rated Danger, or under ${usd} of liquidity or {holders} holders).": "Vom Sicherheitsstandard ausgeblendet: {n} (bewertet mit Gefahr oder unter ${usd} Liquidität oder {holders} Haltern).",
  "Show them": "Anzeigen",
  "Stock": "Aktie",
  "Safety ratings here come from market data: on-chain checks run on Arc.": "Die Sicherheitsbewertungen hier stammen aus Marktdaten: On-Chain-Prüfungen laufen auf Arc.",
  "The first coin launched with this ticker; the others are duplicates.": "Der erste Coin, der mit diesem Ticker gestartet wurde; die anderen sind Duplikate.",
  "A later coin using the OG’s ticker: not the original.": "Ein späterer Coin mit dem Ticker des OG: nicht das Original.",
  "⚠ DUPLICATE": "⚠ DUPLIKAT",
  "Launched again by the creator of the OG coin with this ticker.": "Erneut gestartet vom Ersteller des OG-Coins mit diesem Ticker.",
  "⚠ DUPLICATE · SAME CREATOR": "⚠ DUPLIKAT · GLEICHER ERSTELLER",
  "duplicates": "Duplikate",
  "Duplicate": "Duplikat",
  "Of the fees ARCDEX collects, 30% buy back $ARCDEX and burn it, and 70% go to liquidity pools. Every number is read from the fee wallet on-chain.": "Von den Gebühren, die ARCDEX einnimmt, kaufen 30 % $ARCDEX zurück und verbrennen ihn, 70 % gehen in Liquiditätspools. Jede Zahl wird on-chain aus der Gebühren-Wallet gelesen.",
  "Every listed coin, live, with a safety rating.": "Jeder gelistete Coin, live, mit Sicherheitsbewertung.",
  "Any listed coin for USDC, in one step.": "Jeden gelisteten Coin gegen USDC, in einem Schritt.",
  "Move USDC in and out in about a minute.": "USDC rein und raus in etwa einer Minute.",
  "A multichain decentralized exchange: spot trading, one-tap swaps, a USDC bridge, and BTC, ETH and SOL perpetual futures, now on testnet.": "Eine dezentrale Multichain-Börse: Spot-Trading, Swaps mit einem Tipp, eine USDC-Bridge und Perpetual Futures auf BTC, ETH und SOL, jetzt im Testnet.",
  "ARCDEX’s platform coin. 30% of ARCDEX’s fees buy back $ARCDEX and burn it, and 70% go to liquidity pools. Every buyback and burn is on-chain and shown live on this page.": "Der Plattform-Coin von ARCDEX. 30 % der Gebühren von ARCDEX kaufen $ARCDEX zurück und verbrennen ihn, 70 % gehen in Liquiditätspools. Jeder Rückkauf und jede Verbrennung ist on-chain und wird live auf dieser Seite gezeigt.",
  "Open the app, create a trading wallet or connect your own, add USDC, then buy $ARCDEX on its trading page. Always check the contract address: {ca}.": "Öffne die App, erstelle eine Trading-Wallet oder verbinde deine eigene, füge USDC hinzu und kaufe dann $ARCDEX auf seiner Handelsseite. Prüfe immer die Vertragsadresse: {ca}.",
  "Coins launched on a launchpad with $15K or more of market cap, and stock tokens. Coins from unknown contracts and coins that have rugged aren’t listed.": "Auf einem Launchpad gestartete Coins mit 15.000 $ oder mehr Marktkapitalisierung sowie Aktien-Token. Coins aus unbekannten Verträgen und Coins, die gerugged wurden, werden nicht gelistet.",
  "They’re on testnet now: try them with free test USDC, without risk. Mainnet follows an independent security audit; the date will be announced.": "Sie laufen jetzt im Testnet: Probiere sie mit kostenlosem Test-USDC ohne Risiko aus. Das Mainnet folgt nach einem unabhängigen Sicherheitsaudit; das Datum wird angekündigt.",
  "Yes. Meme coins are very volatile, and futures with leverage can lose money quickly. Trade only what you can afford to lose. Nothing here is financial advice.": "Ja. Meme-Coins sind sehr volatil, und Futures mit Hebel können schnell Geld verlieren. Handle nur mit dem, was du dir leisten kannst zu verlieren. Nichts hier ist eine Finanzberatung.",
  "Multichain DEX · spot & futures": "Multichain-DEX · Spot & Futures",
  "The multichain decentralized exchange for spot and futures. 30% of every fee buys back $ARCDEX and burns it.": "Die dezentrale Multichain-Börse für Spot und Futures. 30 % jeder Gebühr kaufen $ARCDEX zurück und verbrennen ihn.",
  "Live markets": "Live-Märkte",
  "No new coin has reached $15K of market cap yet.": "Noch kein neuer Coin hat 15.000 $ Marktkapitalisierung erreicht.",
  "Long or short BTC, ETH and SOL with up to 10× leverage, settled in USDC at RedStone’s signed oracle prices. On testnet now; mainnet after an independent audit.": "Long oder Short auf BTC, ETH und SOL mit bis zu 10× Hebel, abgerechnet in USDC zu den signierten Oracle-Preisen von RedStone. Vorerst im Testnet; Mainnet nach einem unabhängigen Audit.",
  "Everything to trade, in one place": "Alles zum Traden, an einem Ort",
  "Connecting…": "Verbinde…",
  "Arc CA": "Arc-CA",
  "How far along its launchpad’s curve, as the launchpad counts it": "Wie weit auf der Kurve seines Launchpads, wie das Launchpad es zählt",
  "Selling is signed on Solana and costs a fraction of a cent in SOL: one tap adds some.": "Verkäufe werden auf Solana signiert und kosten einen Bruchteil eines Cents in SOL: ein Tipp fügt welches hinzu.",
  "All launchpads": "Alle Launchpads",
  "Sort: bonding progress": "Sortierung: Kurvenfortschritt",
  "Loading Solana…": "Solana wird geladen…",
  "Prices and trades from GeckoTerminal; launch curves and mints read from Solana. Coins on Solana are launched by anyone: check a coin before you buy it.": "Preise und Trades von GeckoTerminal; Launch-Kurven und Mints von Solana gelesen. Coins auf Solana kann jeder starten: prüfe einen Coin, bevor du kaufst.",
  "Not a launchpad coin: ARCDEX only lists and sells coins launched on a launchpad, because coins from unknown contracts can be malicious. You can still sell any you hold.": "Kein Launchpad-Coin: ARCDEX listet und verkauft nur auf einem Launchpad gestartete Coins, weil Coins aus unbekannten Verträgen bösartig sein können. Gehaltene Coins kannst du weiterhin verkaufen.",
  "This coin’s mint can still freeze or inflate it, so ARCDEX doesn’t offer it to buy. You can still sell any you hold.": "Der Mint dieses Coins kann ihn noch einfrieren oder aufblähen, daher bietet ARCDEX ihn nicht zum Kauf an. Gehaltene Coins kannst du weiterhin verkaufen.",
  "Trades on Solana, from GeckoTerminal": "Trades auf Solana, von GeckoTerminal",
  "On {pad}’s bonding curve": "Auf der Bonding-Kurve von {pad}",
  "its launchpad": "seinem Launchpad",
  "Solana markets": "Solana-Märkte",
  "Not enough SOL for fees on Solana: add SOL first.": "Nicht genug SOL für Gebühren auf Solana: füge zuerst SOL hinzu.",
  "Relay’s route changed since your quote: check the new quote and try again.": "Relays Route hat sich seit deinem Angebot geändert: prüfe das neue Angebot und versuche es erneut.",
  "Relay’s transaction couldn’t be built: try again.": "Relays Transaktion konnte nicht gebaut werden: versuche es erneut.",
  "The sale would fail: {why}": "Der Verkauf würde scheitern: {why}",
  "This sale would cost more SOL than a sale’s fees, so ARCDEX won’t send it.": "Dieser Verkauf würde mehr SOL kosten als die Gebühren eines Verkaufs, daher sendet ARCDEX ihn nicht.",
  "Relay can’t route this coin right now: it may have too little liquidity, or a token setup Relay doesn’t trade.": "Relay kann diesen Coin gerade nicht routen: zu wenig Liquidität, oder ein Token-Aufbau, den Relay nicht handelt.",
  "This amount is below what Relay can route: try a little more.": "Dieser Betrag liegt unter dem, was Relay routen kann: versuche etwas mehr.",
