  "The best route loses {n}% of this trade to price impact, so ARCDEX won’t send it. A smaller amount may route better.": "Die beste Route verliert {n} % dieses Trades an Preiseinfluss, daher sendet ARCDEX ihn nicht. Ein kleinerer Betrag lässt sich vielleicht besser routen.",
