  "Graduated coins: pay with USDC on Arc, BNB or USDT. The coin lands at your same address on BNB Chain.": "Graduierte Coins: Bezahle mit USDC auf Arc, BNB oder USDT. Der Coin landet unter deiner selben Adresse auf BNB Chain.",
  "Launched by four.meme: its contract vouches for this coin": "Von four.meme gestartet: Sein Vertrag bürgt für diesen Coin",
  "Loading BNB Chain…": "BNB Chain wird geladen…",
  "No Solana wallet app found in this browser: install Phantom, or use your trading wallet, which has a Solana address too.": "Keine Solana-Wallet-App in diesem Browser gefunden: Installiere Phantom oder nutze deine Trading-Wallet, die ebenfalls eine Solana-Adresse hat.",
