  "Pay with SOL or USDC from your Solana wallet (Phantom, Solflare…), or with USDC on Arc: the coin lands in your Solana wallet in seconds.": "Bezahle mit SOL oder USDC aus deiner Solana-Wallet (Phantom, Solflare…) oder mit USDC auf Arc: Der Coin landet in Sekunden in deiner Solana-Wallet.",
  "Pay with SOL, USDC on Solana or USDC on Arc, and sell for any of them: SOL and Solana USDC through Jupiter, USDC on Arc through Relay. Every trade is checked and simulated before it’s sent, and approvals are for the exact amount.": "Bezahlen Sie mit SOL, USDC auf Solana oder USDC auf Arc und verkaufen Sie gegen jedes davon: SOL und Solana-USDC über Jupiter, USDC auf Arc über Relay. Jeder Trade wird vor dem Senden geprüft und simuliert, und Freigaben gelten genau für den Betrag.",
