  "Prices and trades from GeckoTerminal; curves and graduation read from four.meme’s contract on BNB Chain. Coins on four.meme are launched by anyone: check a coin before you buy it.": "Preise und Trades von GeckoTerminal; Kurven und Graduierung aus dem Vertrag von four.meme auf BNB Chain gelesen. Auf four.meme kann jeder Coins starten: Prüfe einen Coin, bevor du ihn kaufst.",
