  "Pay with SOL or USDC from your Solana wallet: the coin lands in your ARCDEX account on {chain} in seconds. Sell it back for SOL or USDC any time. Every trade is checked and simulated before it’s sent.": "Zahle mit SOL oder USDC aus deiner Solana-Wallet: Der Coin landet in Sekunden auf deinem ARCDEX-Konto auf {chain}. Verkaufe ihn jederzeit zurück gegen SOL oder USDC. Jeder Trade wird vor dem Senden geprüft und simuliert.",
