  "Predictions are paid from your spot USDC. Make your account unified (Enable trading) or move USDC to spot on Hyperliquid.": "Vorhersagen werden aus deinen Spot-USDC bezahlt. Mach dein Konto zum Unified-Konto (Trading aktivieren) oder verschiebe USDC auf Hyperliquid in den Spot.",
