  "None": "Keine",
  "Each contract pays $1 if its side happens and nothing if not. Hyperliquid settles it by itself.": "Jeder Kontrakt zahlt 1 $, wenn seine Seite eintritt, sonst nichts. Hyperliquid rechnet selbst ab.",
  "How it settles": "Wie abgerechnet wird",
