  "Predictions": "Vorhersagen",
  "Trade on what happens next: crypto prices, stocks, sports and the economy. Each side pays $1 if it’s right, settled by Hyperliquid.": "Handle, was als Nächstes passiert: Kryptopreise, Aktien, Sport und Wirtschaft. Jede richtige Seite zahlt 1 $, abgerechnet von Hyperliquid.",
