  "Ending soon": "Enden bald",
  "Most outcomes": "Meiste Ausgänge",
  "Markets, prices and settlement are Hyperliquid’s: orders are signed in your browser and go straight to it. ARCDEX never holds your money.": "Märkte, Preise und Abrechnung sind die von Hyperliquid: Orders werden in deinem Browser signiert und gehen direkt dorthin. ARCDEX verwahrt nie dein Geld.",
  "ARCDEX’s fee applies only when you sell, as a Hyperliquid builder fee you approve once.": "Die ARCDEX-Gebühr fällt nur beim Verkauf an, als Hyperliquid-Builder-Gebühr, die du einmal freigibst.",
  "You cancelled it in your wallet.": "Du hast es in deiner Wallet abgebrochen.",
  "Checking where you are…": "Dein Standort wird geprüft…",
  "We couldn’t confirm your location, so opening positions is off. Closing positions and withdrawing always work.": "Wir konnten deinen Standort nicht bestätigen, daher ist das Eröffnen von Positionen aus. Schließen und Auszahlen funktionieren immer.",
  "Hyperliquid isn’t available to US persons, Ontario or sanctioned regions. Closing positions and withdrawing always work.": "Hyperliquid ist nicht für US-Personen, Ontario oder sanktionierte Regionen verfügbar. Schließen und Auszahlen funktionieren immer.",
  "Your trading wallet signs each step itself: no pop-ups.": "Deine Trading-Wallet signiert jeden Schritt selbst: keine Pop-ups.",
  "Your wallet asks you to sign each step once. Nothing is sent on-chain and no gas is paid.": "Deine Wallet bittet dich, jeden Schritt einmal zu signieren. Nichts geht on-chain, und es fällt kein Gas an.",
  "Deposited: your USDC is in your Hyperliquid account.": "Eingezahlt: Deine USDC sind auf deinem Hyperliquid-Konto.",
