  "Relay refunded it: the USDC went back where it came from.": "Relay hat erstattet: Die USDC sind zurück, wo sie herkamen.",
  "Still on its way: it usually lands within a minute. Your balance updates by itself.": "Noch unterwegs: Es kommt meist innerhalb einer Minute an. Dein Guthaben aktualisiert sich von selbst.",
