  "Where do futures and predictions trade?": "Wo werden Futures und Vorhersagen gehandelt?",
  "On Hyperliquid, the largest on-chain futures exchange. Your orders are signed in your browser and go straight to it, and ARCDEX never holds your money. Not available to US persons or in sanctioned regions.": "Auf Hyperliquid, der größten On-Chain-Futures-Börse. Deine Orders werden in deinem Browser signiert und gehen direkt dorthin, und ARCDEX verwahrt nie dein Geld. Nicht verfügbar für US-Personen oder in sanktionierten Regionen.",
  "Long or short crypto, stocks, gold, oil and indices with up to 40× leverage, on Hyperliquid’s order books. Orders are signed in your browser; ARCDEX never holds your money.": "Long oder short auf Krypto, Aktien, Gold, Öl und Indizes mit bis zu 40× Hebel, in den Orderbüchern von Hyperliquid. Orders werden in deinem Browser signiert; ARCDEX verwahrt nie dein Geld.",
