  "Hyperliquid’s spot tokens and vaults": "Hyperliquids Spot-Tokens und Vaults",
  // Paper trading on Hyperliquid (2026-10-12)
  "Paper trading uses virtual USDC against Hyperliquid’s live prices and order book. Fills, fees (ARCDEX’s included), Hyperliquid’s hourly funding and liquidations are worked out in this browser; the market impact of your own orders and partial fills aren’t. Nothing is sent to Hyperliquid.": "Papierhandel nutzt virtuelles USDC zu den Live-Preisen und dem Orderbuch von Hyperliquid. Ausführungen, Gebühren (die von ARCDEX eingeschlossen), das stündliche Funding von Hyperliquid und Liquidationen werden in diesem Browser berechnet; die Marktwirkung deiner eigenen Orders und Teilausführungen nicht. Nichts wird an Hyperliquid gesendet.",
  "Practise with virtual USDC": "Mit virtuellem USDC üben",
  "Paper order filled: {sz} {symbol} at {px}": "Papierorder ausgeführt: {sz} {symbol} zu {px}",
  "Paper order placed: it fills when the price reaches it.": "Papierorder platziert: Sie wird ausgeführt, sobald der Preis sie erreicht.",
  "Virtual USDC, Hyperliquid’s live prices": "Virtuelles USDC, Live-Preise von Hyperliquid",
  "Paper positions use isolated margin: a loss stops at the position’s margin.": "Papierpositionen nutzen isolierte Margin: Ein Verlust endet bei der Margin der Position.",
  "Your open position’s leverage. Close it to change.": "Der Hebel deiner offenen Position. Schließe sie, um ihn zu ändern.",
  "Filling…": "Wird ausgeführt…",
  "Catching up on the prices you missed…": "Verpasste Preise werden nachgeholt…",
  "Reset paper account": "Papierkonto zurücksetzen",
  "Every paper position, order and trade is cleared, and the account starts again with:": "Alle Papierpositionen, -orders und -trades werden gelöscht, und das Konto startet neu mit:",
  "Reset to {amount}": "Auf {amount} zurücksetzen",
  "No open paper positions.": "Keine offenen Papierpositionen.",
