  "While you were away ({span}), from Hyperliquid’s candles:": "Während du weg warst ({span}), laut den Kerzen von Hyperliquid:",
  "Prices for the last {span} couldn’t be loaded, so your paper orders weren’t checked then. They’re watched again from now.": "Die Preise der letzten {span} konnten nicht geladen werden, deshalb wurden deine Papierorders in dieser Zeit nicht geprüft. Ab jetzt werden sie wieder überwacht.",
