  "reached {time}": "erreicht {time}",
  "Alerts are watched while ARCDEX is open in this browser, on any page. If a level is reached while it’s closed, you’re told when you come back, from Hyperliquid’s candles. Up to {n} at a time.": "Alarme werden überwacht, solange ARCDEX in diesem Browser offen ist, auf jeder Seite. Wird ein Wert erreicht, während es geschlossen ist, erfährst du es bei deiner Rückkehr, anhand der Kerzen von Hyperliquid. Bis zu {n} gleichzeitig.",
  "No price alerts. Set one with the 🔔 next to the market’s price.": "Keine Preisalarme. Setze einen mit der 🔔 neben dem Marktpreis.",
  "Alert": "Alarm",
  "Set": "Gesetzt",
  "Clear reached": "Erreichte löschen",
  "Waiting": "Wartet",
  "Reached {time}": "Erreicht {time}",
