  "Swap Starknet tokens at the best price across Starknet’s exchanges, routed by AVNU. Your wallet signs every transaction; ARCDEX never holds your coins.": "Tausche Starknet-Token zum besten Preis über Starknets Börsen, geroutet von AVNU. Deine Wallet signiert jede Transaktion; ARCDEX verwahrt nie deine Coins.",
