  "Connect {name}": "{name} verbinden",
  "No Starknet wallet found in this browser. Install one, then reload:": "Keine Starknet-Wallet in diesem Browser. Installiere eine und lade neu:",
  "Check your wallet on testnet": "Wallet im Testnet prüfen",
  "Signs a transfer of 0 STRK to yourself on Starknet Sepolia, then waits for it to be confirmed. Nothing of value moves; the testnet fee is paid in Sepolia STRK.": "Signiert eine Überweisung von 0 STRK an dich selbst auf Starknet Sepolia und wartet auf die Bestätigung. Nichts von Wert wird bewegt; die Testnet-Gebühr wird in Sepolia-STRK bezahlt.",
  "Waiting for Sepolia…": "Warten auf Sepolia…",
  "Send a 0 STRK test transaction": "0-STRK-Testtransaktion senden",
  "Connect a wallet first.": "Verbinde zuerst eine Wallet.",
  "Sepolia STRK from the Starknet Foundation’s faucet": "Sepolia-STRK vom Faucet der Starknet Foundation",
  "Before you sign": "Bevor du signierst",
  "AVNU finds the best route across Starknet’s exchanges and quotes it.": "AVNU findet die beste Route über Starknets Börsen und bepreist sie.",
  "ARCDEX checks the transaction AVNU builds: an approval of exactly your amount to AVNU’s Exchange, your address as the one paid, and a minimum within your slippage.": "ARCDEX prüft die Transaktion, die AVNU baut: eine Freigabe von genau deinem Betrag an AVNUs Exchange, deine Adresse als Empfänger und ein Minimum innerhalb deiner Slippage.",
  "Your wallet signs; the swap settles on Starknet in seconds, and you can follow it on Voyager.": "Deine Wallet signiert; der Tausch wird in Sekunden auf Starknet abgewickelt, und du kannst ihn auf Voyager verfolgen.",
  "Every supported route": "Alle unterstützten Routen",
  "AVNU is busy right now: try again in a moment.": "AVNU ist gerade ausgelastet: versuche es gleich noch einmal.",
  "There’s no route for this swap right now.": "Für diesen Tausch gibt es gerade keine Route.",
  "AVNU’s quote didn’t match the swap asked for": "AVNUs Angebot passte nicht zum gewünschten Tausch",
  "That quote has expired: get a new one.": "Dieses Angebot ist abgelaufen: hol ein neues.",
  "AVNU’s transaction didn’t match the swap asked for": "AVNUs Transaktion passte nicht zum gewünschten Tausch",
  "Starknet tokens": "Starknet-Token",
  "Starknet tokens (AVNU’s verified list)": "Starknet-Token (verifizierte Liste von AVNU)",
  "Signed by your Starknet wallet; AVNU’s own 0.1% applies. A 0 STRK test transaction checks a wallet on Sepolia.": "Von deiner Starknet-Wallet signiert; AVNUs eigene 0,1 % fallen an. Eine 0-STRK-Testtransaktion prüft eine Wallet auf Sepolia.",
