  "These are the nodes ARCDEX reads {chain} through: balances, quotes, and the simulation every trade runs before you sign. The first one is used; a node that throttles or fails steps aside for 30 seconds and the next answers. Put a node first if it’s faster: the numbers below are measured from this browser, right now.": "Über diese Nodes liest ARCDEX {chain}: Guthaben, Kurse und die Simulation, die jeder Trade vor deiner Signatur durchläuft. Der erste wird benutzt; ein Node, der drosselt oder ausfällt, tritt 30 Sekunden zur Seite und der nächste antwortet. Setz einen Node nach vorn, wenn er schneller ist: Die Zahlen unten sind in diesem Browser gemessen, jetzt gerade.",
