  "1 coin hidden by the listing rules (rugged, rated Danger, too thin, or under $15,000 of market cap).": "1 Coin von den Listing-Regeln ausgeblendet (gerugt, mit Gefahr bewertet, zu dünn oder unter 15.000 $ Marktkapitalisierung).",
  "{n} coins hidden by the listing rules (rugged, rated Danger, too thin, or under $15,000 of market cap).": "{n} Coins von den Listing-Regeln ausgeblendet (gerugt, mit Gefahr bewertet, zu dünn oder unter 15.000 $ Marktkapitalisierung).",
  "Show everything": "Alles zeigen",
