  // Alchemy and fastest-first RPC (2026-10-12)
  "These are the nodes ARCDEX reads {chain} through: balances, quotes, and the simulation every trade runs before you sign. This browser measures them every 2 minutes and reads through the fastest one that is up to date; a node that throttles or fails steps aside and the next answers. Pin another with Use first.": "Über diese Nodes liest ARCDEX {chain}: Guthaben, Kurse und die Simulation, die jeder Trade vor deiner Signatur durchläuft. Dieser Browser misst sie alle 2 Minuten und liest über den schnellsten, der aktuell ist; ein Node, der drosselt oder ausfällt, tritt zur Seite und der nächste antwortet. Mit „Zuerst nutzen“ fixierst du einen anderen.",
  "ARCDEX’s Alchemy node": "Alchemy-Node von ARCDEX",
  // Trenches live feed, smart money and the coin bar (2026-10-12)
  "Buy opens Arc’s trade form with this slippage": "Kaufen öffnet Arcs Handelsformular mit dieser Slippage",
  "Wallets with a winning record on this chain, measured by ARCDEX": "Wallets mit Gewinnbilanz auf dieser Chain, gemessen von ARCDEX",
  "smart wallets": "Smart Wallets",
  "Smart": "Smart",
  "Show {lane}": "{lane} anzeigen",
  "A wallet counts as smart after {n}+ closed trades on {chain}, {w}+ of them won, {p}+ in profit, holding over {s}s on average (bots that flip in seconds don’t count). Measured from the trades ARCDEX has seen since {since}.": "Ein Wallet gilt als smart nach {n}+ abgeschlossenen Trades auf {chain}, davon {w}+ gewonnen, {p}+ Gewinn, im Schnitt über {s}s gehalten (Bots, die in Sekunden drehen, zählen nicht). Gemessen an den Trades, die ARCDEX seit {since} gesehen hat.",
  "{n} wallets": "{n} Wallets",
  "Buying now": "Kaufen gerade",
  "Minimize": "Minimieren",
  "Connecting to the live feed…": "Verbinde mit dem Live-Feed…",
  "Learning which wallets win on {chain}": "Lernt, welche Wallets auf {chain} gewinnen",
  "{n} wallets followed since {since}. None has a winning record yet.": "{n} Wallets verfolgt seit {since}. Noch keines hat eine Gewinnbilanz.",
  "No smart wallet has bought in the last {m} minutes.": "Kein Smart Wallet hat in den letzten {m} Minuten gekauft.",
  "No smart wallet has traded yet since you opened this page.": "Seit du diese Seite geöffnet hast, hat noch kein Smart Wallet gehandelt.",
  "This wallet: {n} closed trades, {w} won, {p} realized": "Dieses Wallet: {n} abgeschlossene Trades, {w} gewonnen, {p} realisiert",
  "Smart = a winning record on {chain}, measured by ARCDEX from on-chain trades. Not advice.": "Smart = Gewinnbilanz auf {chain}, von ARCDEX aus On-Chain-Trades gemessen. Keine Beratung.",
  "1 smart wallet": "1 Smart Wallet",
  "{n} smart wallets": "{n} Smart Wallets",
  "Smart wallets selling it": "Smart Wallets, die verkaufen",
