  "last buy {age} ago": "letzter Kauf vor {age}",
  "Open $ARCDEX": "$ARCDEX öffnen",
  "$ARCDEX held by the dead address 0x…dEaD, read from Arc: gone for good.": "$ARCDEX auf der toten Adresse 0x…dEaD, von Arc gelesen: für immer weg.",
  "{p}% of supply": "{p} % des Angebots",
  "Amount in {unit}": "Betrag in {unit}",
  "Opens its trade form with this amount: you confirm there.": "Öffnet sein Handelsformular mit diesem Betrag: Du bestätigst dort.",
  "Trading on {venue} is paused: {reason}": "Der Handel auf {venue} ist pausiert: {reason}",
  "Trading is paused everywhere: {reason}": "Der Handel ist überall pausiert: {reason}",
  "Withdrawals and transfers still work.": "Auszahlungen und Überweisungen funktionieren weiterhin.",
  "Every venue": "Alle Handelsplätze",
  "Write a reason first (3 characters or more): it goes in the audit log and on the banner.": "Gib zuerst einen Grund an (mindestens 3 Zeichen): Er kommt ins Audit-Log und auf das Banner.",
  "Trading is back on: {where}.": "Der Handel ist wieder an: {where}.",
  "Trading is off: {where}. New trades there are refused before signing.": "Der Handel ist aus: {where}. Neue Trades dort werden vor dem Signieren abgelehnt.",
  "Trade switch": "Handelsschalter",
  "Turn trading off everywhere or on one venue. New trades there are refused before anything is signed; withdrawals, transfers and the bridge keep working, and Hyperliquid positions can still be closed. Only an admin wallet can change it, and every change is kept in the audit log.": "Schalte den Handel überall oder auf einem Handelsplatz ab. Neue Trades dort werden abgelehnt, bevor etwas signiert wird; Auszahlungen, Überweisungen und die Bridge funktionieren weiter, und Hyperliquid-Positionen lassen sich weiterhin schließen. Nur eine Admin-Wallet kann ihn ändern, und jede Änderung wird im Audit-Log festgehalten.",
  "The engine isn’t configured on this build, so the switch can’t be read.": "Die Engine ist in diesem Build nicht konfiguriert, daher kann der Schalter nicht gelesen werden.",
  "Reading…": "Wird gelesen…",
  "Trading is on everywhere": "Der Handel ist überall an",
  "Trading is off somewhere": "Der Handel ist irgendwo aus",
  "Read again": "Neu lesen",
  "Set on the engine (Railway): only removing it there turns it back on.": "Auf der Engine gesetzt (Railway): Nur das Entfernen dort schaltet ihn wieder ein.",
  "Turn on": "Einschalten",
  "Turn off": "Ausschalten",
  "Reason (shown on the banner and kept in the audit log)": "Grund (auf dem Banner angezeigt und im Audit-Log festgehalten)",
  "e.g. Router incident, investigating": "z. B. Router-Vorfall, wird untersucht",
  "Sign with": "Signieren mit",
  "Unlock the trading wallet or connect a wallet to sign.": "Entsperre die Trading-Wallet oder verbinde eine Wallet zum Signieren.",
  "Recent changes": "Letzte Änderungen",
  "{name}’s fee is now {pct}.": "Die Gebühr von {name} beträgt jetzt {pct}.",
  "Spot fee: {pct} everywhere (owner’s decision, 2026-10-15). Fees off Arc are set by the site; the Arc routers’ fee is on-chain and only their owner can change it.": "Spot-Gebühr: überall {pct} (Entscheidung des Eigentümers, 2026-10-15). Gebühren außerhalb von Arc legt die Website fest; die der Arc-Router ist on-chain, und nur ihr Eigentümer kann sie ändern.",
  "Fee {pct} · referrers {share} of it": "Gebühr {pct} · {share} davon an Werber",
  "Sign with the router’s owner ({owner}) to change it.": "Mit dem Eigentümer des Routers ({owner}) signieren, um sie zu ändern.",
  "Set to {pct}": "Auf {pct} setzen",
  "not the site’s fee wallet: its owner changes it with setFeeWallet": "nicht die Gebühren-Wallet der Website: Ihr Eigentümer ändert sie mit setFeeWallet",
  "Solana, BNB Chain, Robinhood Chain": "Solana, BNB Chain, Robinhood Chain",
