  "Daily limit: {left} left until {time}. Sending back to the wallet that funded this one has no limit.": "Tageslimit: noch {left} bis {time}. Zurück an die Wallet, die diese aufgeladen hat, gilt kein Limit.",
  "This address is new: {left} can go now, the full amount from {time}.": "Diese Adresse ist neu: {left} gehen jetzt, der volle Betrag ab {time}.",
  "This address is new: {left} can go now. Save it to send the full amount 24 hours from now.": "Diese Adresse ist neu: {left} gehen jetzt. Speichere sie, um in 24 Stunden den vollen Betrag zu senden.",
  "Enter an Arc address: 0x and 40 letters or numbers.": "Gib eine Arc-Adresse ein: 0x und 40 Buchstaben oder Ziffern.",
  "That’s the zero address: anything sent there is lost.": "Das ist die Null-Adresse: Alles, was dorthin geht, ist verloren.",
  "That’s this wallet’s own address.": "Das ist die eigene Adresse dieser Wallet.",
