  "{what} sent to {to}": "{what} an {to} gesendet",
  "From your ARCDEX trading wallet. If this wasn’t you, move the rest of your funds back to the wallet that funded it now.": "Aus deiner ARCDEX-Trading-Wallet. Warst du das nicht, schick den Rest deines Guthabens jetzt zurück an die Wallet, die sie aufgeladen hat.",
  "New withdrawal address saved: {to}": "Neue Auszahlungsadresse gespeichert: {to}",
