  "Transfers on Arc can’t be reversed. Check the address matches the one you meant, character by character at the ends.": "Überweisungen auf Arc lassen sich nicht rückgängig machen. Prüfe, ob die Adresse die gemeinte ist, Zeichen für Zeichen an den Enden.",
