  "Jupiter’s transaction names a table Solana doesn’t have: try again.": "Jupiters Transaktion nennt eine Tabelle, die Solana nicht hat: versuch es noch einmal.",
  "This trade would take more than the amount shown, so ARCDEX won’t send it.": "Dieser Trade würde mehr als den angezeigten Betrag nehmen, daher sendet ARCDEX ihn nicht.",
