  "Jupiter (Relay while Jupiter isn’t on)": "Jupiter (Relay, solange Jupiter nicht eingeschaltet ist)",
  "A swap on Solana alone, signed by your Solana wallet. Through Jupiter, ARCDEX’s fee is paid in the same transaction.": "Ein Swap nur auf Solana, signiert von deiner Solana-Wallet. Über Jupiter wird die Gebühr von ARCDEX in derselben Transaktion bezahlt.",
  "Solana swaps (Jupiter)": "Solana-Swaps (Jupiter)",
  "Fee {pct} (Jupiter referral fee, paid in the transaction)": "Gebühr {pct} (Jupiter-Empfehlungsgebühr, in der Transaktion bezahlt)",
  "Not on: set VITE_JUP_REFERRAL_ACCOUNT and JUPITER_API_KEY on Netlify (Relay trades them meanwhile)": "Nicht aktiv: VITE_JUP_REFERRAL_ACCOUNT und JUPITER_API_KEY auf Netlify setzen (bis dahin handelt Relay sie)",
  "Fee ledger": "Gebührenbuch",
  "Every fee the engine read on-chain, kept for good (rows are never changed or removed). Each night it checks the ledger against the chain: Arc receipts block by block, and the balances Relay and Jupiter hold for the fee wallet.": "Jede Gebühr, die die Engine on-chain gelesen hat, dauerhaft gespeichert (Zeilen werden nie geändert oder gelöscht). Jede Nacht gleicht sie das Buch mit der Chain ab: Arc-Belege Block für Block und die Guthaben, die Relay und Jupiter für die Gebühren-Wallet halten.",
  "Couldn’t read the ledger: {why}": "Das Buch konnte nicht gelesen werden: {why}",
