  "Admin": "Admin",
  "Sign in with an admin wallet to see who’s online, fees, trades and the audit log, and to change flags or run the fee sweeper. Every change asks for your wallet’s signature again and is kept in the audit log. The kill switch and the routers’ fee work without signing in.": "Melden Sie sich mit einer Admin-Wallet an, um zu sehen, wer online ist, Gebühren, Trades und das Audit-Protokoll, und um Flags zu ändern oder den Gebühren-Sweeper zu starten. Jede Änderung verlangt erneut die Signatur Ihrer Wallet und wird im Audit-Protokoll gespeichert. Not-Aus und die Router-Gebühr funktionieren ohne Anmeldung.",
