  "Run the sweep for real? Fees bots owe are sent to the fee wallet; the rest is reported for you to claim.": "Den Sweep wirklich ausführen? Gebühren, die Bots schulden, gehen an die Gebühren-Wallet; der Rest wird Ihnen zum Abholen gemeldet.",
  "Sweep ({mode}): {status}. Sent {sent}; for you to claim {owner}.": "Sweep ({mode}): {status}. Gesendet {sent}; von Ihnen abzuholen {owner}.",
  "dry run": "Probelauf",
  "for real": "echt",
  "Fee sweeper": "Gebühren-Sweeper",
  "Fees are paid to the fee wallet inside each trade. The sweeper finds what still sits elsewhere: fees bots owe (sent to the fee wallet), and fees held at Relay or in Jupiter’s referral account (for you to claim with that wallet). It runs every day; a second run the same day does nothing.": "Gebühren werden in jedem Trade an die Gebühren-Wallet gezahlt. Der Sweeper findet, was noch anderswo liegt: Gebühren, die Bots schulden (an die Gebühren-Wallet gesendet), und Gebühren bei Relay oder auf Jupiters Empfehlungskonto (von Ihnen mit dieser Wallet abzuholen). Er läuft täglich; ein zweiter Lauf am selben Tag tut nichts.",
  "Nothing is held outside the fee wallet.": "Außerhalb der Gebühren-Wallet liegt nichts.",
  "under the threshold": "unter der Schwelle",
  "the sweeper sends it": "der Sweeper sendet es",
  "for you to claim": "von Ihnen abzuholen",
