  "Fees, last 24 hours": "Gebühren, letzte 24 Stunden",
  "From the fee ledger: the trades index (Supabase) isn’t readable from the engine, so each row is a fee received.": "Aus dem Gebührenbuch: Der Trade-Index (Supabase) ist von der Engine aus nicht lesbar, daher ist jede Zeile eine erhaltene Gebühr.",
