  "{flag} is now {state}. Open pages pick it up within 5 minutes.": "{flag} ist jetzt {state}. Offene Seiten übernehmen es innerhalb von 5 Minuten.",
  "Turn a feature on or off for everyone without a deploy. A flag set on Netlify (VITE_FLAG_…) still wins, and protections can only be turned on here: turning one off takes a deploy.": "Schalten Sie eine Funktion ohne Deploy für alle ein oder aus. Ein auf Netlify gesetztes Flag (VITE_FLAG_…) hat weiterhin Vorrang, und Schutzfunktionen können hier nur eingeschaltet werden: Das Ausschalten braucht einen Deploy.",
