  "I understand this coin is rated Danger and I could lose everything I put in.": "Mir ist klar, dass dieser Coin als Gefahr eingestuft ist und ich alles verlieren könnte, was ich einsetze.",
  "Referral rebate": "Empfehlungsrabatt",
  "paid to the referrer": "an den Empfehlenden gezahlt",
  "Referral rebates too: each one against the router’s event, the transfer that paid it, the share of the fee, and the referrer the router holds for that trader.": "Auch Empfehlungsrabatte: jeder gegen das Ereignis des Routers, die Überweisung, die ihn bezahlt hat, den Anteil an der Gebühr und den Empfehlenden, den der Router für diesen Trader führt.",
  "Referral rebates": "Empfehlungsrabatte",
