  "This browser can’t receive alerts with ARCDEX closed. On an iPhone, add ARCDEX to your home screen first.": "Dieser Browser kann bei geschlossenem ARCDEX keine Benachrichtigungen empfangen. Füge ARCDEX auf dem iPhone zuerst zum Home-Bildschirm hinzu.",
