  "ARCDEX’s engine checks every trade on this coin and sends the alert to this device within seconds. A price alert fires once; a whale alert at most once a minute.": "Die ARCDEX-Engine prüft jeden Trade dieses Coins und sendet den Alarm in Sekunden an dieses Gerät. Ein Preisalarm löst einmal aus, ein Wal-Alarm höchstens einmal pro Minute.",
  "email sign-in": "E-Mail-Anmeldung",
