  "Email or social account": "E-Mail- oder Social-Konto",
  "No wallet app: an EVM and a Solana wallet are made for you": "Ohne Wallet-App: Eine EVM- und eine Solana-Wallet werden für dich erstellt",
  "For your safety, sign in again before sending to this address.": "Melde dich zu deiner Sicherheit erneut an, bevor du an diese Adresse sendest.",
  "Sign in again": "Erneut anmelden",
  "This address isn’t one of your own. Privy will ask for your two-step verification code before it sends.": "Diese Adresse gehört nicht dir. Privy fragt vor dem Senden nach deinem Code für die Zwei-Schritt-Bestätigung.",
  "This address isn’t one of your own. For your safety, sign in again (email code or social account) before sending to it. With two-step verification on (Manage account), Privy asks for a code instead.": "Diese Adresse gehört nicht dir. Melde dich zu deiner Sicherheit erneut an (E-Mail-Code oder Social-Konto), bevor du an sie sendest. Mit aktivierter Zwei-Schritt-Bestätigung (Konto verwalten) fragt Privy stattdessen nach einem Code.",
  "To export a key, sign in again first (or turn on two-step verification).": "Um einen Schlüssel zu exportieren, melde dich zuerst erneut an (oder aktiviere die Zwei-Schritt-Bestätigung).",
  "Email & social sign-in": "Anmeldung per E-Mail oder Social Login",
  "Signed in as {who}. Privy made an EVM and a Solana wallet for this account; Privy confirms every transaction in its own window.": "Angemeldet als {who}. Privy hat für dieses Konto eine EVM- und eine Solana-Wallet erstellt; Privy bestätigt jede Transaktion im eigenen Fenster.",
  "your account": "dein Konto",
  "EVM wallet": "EVM-Wallet",
  "Same address on Arc, Ethereum, Arbitrum, BNB Chain and Robinhood Chain": "Dieselbe Adresse auf Arc, Ethereum, Arbitrum, BNB Chain und Robinhood Chain",
  "Being made…": "Wird erstellt…",
  "Two-step verification": "Zwei-Schritt-Bestätigung",
  "Privy asks for a code before keys or money leave the account. Recommended.": "Privy fragt nach einem Code, bevor Schlüssel oder Geld das Konto verlassen. Empfohlen.",
  "Manage": "Verwalten",
  "Privy shows the key in its own window: ARCDEX never sees it. Anyone with the key controls the wallet.": "Privy zeigt den Schlüssel im eigenen Fenster: ARCDEX sieht ihn nie. Wer den Schlüssel hat, kontrolliert die Wallet.",
  "EVM key": "EVM-Schlüssel",
