  "Email sign-in couldn’t be reached. Try again, or use another wallet.": "Die E-Mail-Anmeldung ist nicht erreichbar. Versuche es erneut oder nutze eine andere Wallet.",
  "Sign in to ARCDEX": "Bei ARCDEX anmelden",
  "With your email or a social account. Your EVM and Solana wallets are made for you.": "Mit deiner E-Mail oder einem Social-Konto. Deine EVM- und Solana-Wallets werden für dich erstellt.",
