  "What people reported. A comment or thesis that three different wallets report is hidden until you look at it. Restore or dismiss keeps it up for good; ban stops a wallet posting and hides what it posted.": "Was gemeldet wurde. Ein Kommentar oder eine These, die drei verschiedene Wallets melden, wird ausgeblendet, bis du sie dir ansiehst. Wiederherstellen oder Abweisen lässt sie dauerhaft sichtbar; Sperren hindert eine Wallet am Posten und blendet aus, was sie gepostet hat.",
