  "Verified on-chain": "On-Chain verifiziert",
  "Realized PnL recomputed from ARCDEX’s router trades on Arc (average cost per coin), read from the chain to block {block}.": "Realisierter PnL, neu berechnet aus den Trades der ARCDEX-Router auf Arc (Durchschnittskosten je Coin), aus der Chain gelesen bis Block {block}.",
  "1 wallet left out by the wash-trade filter": "1 Wallet vom Wash-Trading-Filter ausgeschlossen",
