  "From the trade index; the verified board shows when the engine answers.": "Aus dem Trade-Index; die verifizierte Rangliste erscheint, sobald die Engine antwortet.",
  "More about this trader": "Mehr über diesen Trader",
  "You muted this wallet: its theses and comments are hidden for you.": "Du hast diese Wallet stummgeschaltet: Ihre Thesen und Kommentare sind für dich ausgeblendet.",
  "Unmute": "Stummschaltung aufheben",
  "Recomputed from {n} trades through ARCDEX’s routers on Arc, read from the chain to block {block}. Average cost per coin; tokens sold without a cost here don’t count.": "Neu berechnet aus {n} Trades über die ARCDEX-Router auf Arc, aus der Chain gelesen bis Block {block}. Durchschnittskosten je Coin; hier ohne Kosten verkaufte Coins zählen nicht.",
  "Left out of the leaderboards": "Aus den Ranglisten ausgeschlossen",
  "{n} round trips in 30 days, {pct}% of its volume: coins bought and sold straight back for about the same.": "{n} Hin-und-Rück-Trades in 30 Tagen, {pct} % ihres Volumens: Coins gekauft und sofort für etwa denselben Betrag wieder verkauft.",
  "Traded against": "Hat gehandelt gegen",
  "{n} times: the same coin, the other way, within a few blocks.": "{n}-mal: derselbe Coin, in die andere Richtung, wenige Blöcke auseinander.",
