  "Thanks, it’s reported": "Danke, es ist gemeldet",
  "Enough people reported it: it’s hidden until the ARCDEX team looks at it.": "Genug Leute haben es gemeldet: Es ist ausgeblendet, bis das ARCDEX-Team es prüft.",
  "The ARCDEX team reviews reports. It’s hidden once several people report it.": "Das ARCDEX-Team prüft Meldungen. Es wird ausgeblendet, sobald mehrere Leute es melden.",
