  "Copy sells": "Verkäufe kopieren",
  "Copy trading follows Arc wallets: paste an 0x… address.": "Copy-Trading folgt Arc-Wallets: füge eine 0x…-Adresse ein.",
  "That’s your own wallet.": "Das ist deine eigene Wallet.",
  "You can copy up to {n} leaders.": "Du kannst bis zu {n} Leader kopieren.",
  "Followed": "Gefolgt",
  "Pick traders to copy. Your own trading wallet makes the same trades on Arc within seconds, under your rules. Your money never leaves your wallet.": "Wähle Trader zum Kopieren. Deine eigene Trading-Wallet macht dieselben Trades auf Arc innerhalb von Sekunden, nach deinen Regeln. Dein Geld verlässt nie deine Wallet.",
  "Copy trading is switched off for now.": "Copy-Trading ist vorerst ausgeschaltet.",
  "From your trading wallet {w} · {cash} USDC": "Aus deiner Trading-Wallet {w} · {cash} USDC",
  "Copy trading uses your built-in trading wallet, which signs without pop-ups.": "Copy-Trading nutzt deine eingebaute Trading-Wallet, die ohne Pop-ups signiert.",
  "Open the trading wallet": "Trading-Wallet öffnen",
  "Daily budget ($)": "Tagesbudget ($)",
  "Spent today: {n}": "Heute ausgegeben: {n}",
  "Copies happen only while ARCDEX is open in a tab on this device.": "Kopien passieren nur, solange ARCDEX auf diesem Gerät in einem Tab offen ist.",
  "Copying copies losses as faithfully as gains. Meme coins can lose most or all of their value in minutes.": "Kopieren kopiert Verluste genauso getreu wie Gewinne. Meme-Coins können in Minuten fast ihren ganzen Wert verlieren.",
  "Copies are made after the leader trades, at a different price, and some are skipped (your rules, the safety check, the budget, a price that moved).": "Kopien werden nach dem Trade des Leaders gemacht, zu einem anderen Preis, und manche werden übersprungen (deine Regeln, die Sicherheitsprüfung, das Budget, ein Preis, der sich bewegt hat).",
  "Your trading wallet signs every copy by itself, without asking you each time, while copying is on.": "Deine Trading-Wallet signiert jede Kopie selbst, ohne dich jedes Mal zu fragen, solange Kopieren an ist.",
  "Only Arc trades in Uniswap pools are copied for now, not coins still on a launchpad’s curve. Every copy pays ARCDEX’s normal fee and gas.": "Vorerst werden nur Arc-Trades in Uniswap-Pools kopiert, keine Coins, die noch auf der Kurve eines Launchpads sind. Jede Kopie zahlt die normale ARCDEX-Gebühr und Gas.",
  "I understand, and only use money I can afford to lose.": "Ich verstehe das und nutze nur Geld, dessen Verlust ich mir leisten kann.",
  "Leaders": "Leader",
  "Leader’s Arc wallet (0x…)": "Arc-Wallet des Leaders (0x…)",
  "No leaders yet. Paste a wallet, or pick one below.": "Noch keine Leader. Füge eine Wallet ein oder wähle unten eine aus.",
  "Copied coins": "Kopierte Coins",
